// Canadian half of the Home Area / event Location autocomplete, added
// 2026-10-28 when Justin put Canada in scope ("Some of the most prestigious
// rodeos are in Canada... If they rope they are a potential customer").
// Merged with HOME_AREAS (US) by search-places.
//
// Sourced from Natural Resources Canada's Canadian Geographical Names
// Database, national CSV (Open Government Licence - Canada):
// https://ftp.maps.canada.ca/pub/nrcan_rncan/vector/geobase_cgn_toponyme/prov_csv_eng/cgn_canada_csv_eng.zip
//
// Only "Populated Place" records are kept: cities, towns, villages, hamlets,
// rural communities and localities - the Canadian equivalent of the Census
// incorporated places + CDPs in home-areas.ts. Railway points, post offices,
// neighbourhoods inside a city, industrial parks, resorts and former or
// abandoned places are left out. One entry per name per province. The
// "state" field holds the two-letter province/territory code (AB, BC, ...),
// none of which collide with a US state code, so "City, PROV" works
// everywhere "City, ST" already does (codes listed in provinces.ts).
